pub fn is_prime(n: i8) -> bool {
    // By definition, primes are integers >= 2
    if n < 2 {
        return false;
    }

    // Test all possible divisors from 2 up to n-1
    // As soon as we find one that divides n exactly, n is composite.
    for d in 2..n {
        if n % d == 0 {
            return false;
        }
    }

    // No divisors found => n is prime
    true
}

